@push('scripts')
<script>
const systemNotice=(message,type='success')=>{const n=document.querySelector('#notice');n.textContent=message;n.className=`sa-notice ${type} is-visible`;};async function loadSystem(){const {data}=await dfApi('{{ route('superadmin.system.index') }}');document.querySelector('#maintenance-enabled').checked=data.maintenance.enabled;document.querySelector('#settings-list').innerHTML=data.settings.length?data.settings.map(s=>`<div class="sa-health-row"><div><strong>${escapeHtml(s.key)}</strong><small>${s.is_secret?'Secret · ':''}${s.configured?'Configured':'Not configured'}</small></div><span>${s.is_secret?'••••••••':' '+escapeHtml(s.value??'—')}</span></div>`).join(''):'<div class="sa-empty">Chưa có system setting.</div>';};document.querySelector('#maintenance-form').addEventListener('submit',async e=>{e.preventDefault();try{await dfApi('{{ route('superadmin.system.maintenance.update') }}',{method:'PUT',body:{enabled:document.querySelector('#maintenance-enabled').checked,starts_at:document.querySelector('#maintenance-starts').value||null,ends_at:document.querySelector('#maintenance-ends').value||null}});systemNotice('Đã lưu maintenance settings.');}catch(error){systemNotice(error.message,'error');}});async function resetSystem(){const password=prompt('Nhập mật khẩu superadmin');if(!password)return;const phrase=prompt('Nhập chính xác RESET DRINKFLOW');if(!phrase)return;if(!confirm('Thao tác này không thể hoàn tác. Tiếp tục?'))return;try{await dfApi('{{ route('superadmin.system.reset') }}',{method:'POST',body:{password,phrase}});systemNotice('Đã reset hệ thống.');}catch(error){systemNotice(error.message,'error');}}loadSystem();
</script>
@endpush
